-- =============================================================================
-- 0002_feedback_tables.sql
-- Rural Healthcare Multilingual Feedback Agent — Supabase phase 1
--
-- Purpose : feedback_sessions + feedback_answers (mirror of the existing
--           SQLite schema, with camp scoping and preserved integer IDs).
-- Target  : Supabase SQL Editor (free tier). Safe to re-run (idempotent).
-- Notes   :
--   * bigint identity (GENERATED BY DEFAULT) so existing SQLite row IDs
--     (sessions 1..N, answers 1..M) can be imported unchanged.
--   * UNIQUE (session_id, question_number) preserves the SQLite constraint.
--   * Only fields the application already uses are modelled.
-- =============================================================================

create table if not exists public.feedback_sessions (
    id              bigint generated by default as identity primary key,
    camp_id         uuid not null
                    default '00000000-0000-0000-0000-000000000001'
                    references public.camps (id),
    patient_code    text not null,
    patient_name    text,
    village         text,
    language        text not null,
    consent_given   boolean not null default true,
    status          text not null default 'in_progress'
                    check (status in ('in_progress', 'completed', 'resolved')),
    created_at      timestamptz not null default current_timestamp,
    completed_at    timestamptz
);

comment on table public.feedback_sessions is
    'One row per patient feedback interview session (camp-scoped).';

create table if not exists public.feedback_answers (
    id                  bigint generated by default as identity primary key,
    session_id          bigint not null
                        references public.feedback_sessions (id) on delete cascade,
    question_number     integer not null,
    question_text       text not null,
    transcript          text not null,
    response_type       text not null,
    rating              integer,
    english_translation text,
    translation_status  text not null default 'pending'
                        check (translation_status in
                               ('pending', 'translated', 'failed', 'not_required')),
    translation_engine  text,
    source_language     text,
    created_at          timestamptz not null default current_timestamp,
    constraint uq_answers_session_question unique (session_id, question_number)
);

comment on table public.feedback_answers is
    'One row per question per session. Holds the ORIGINAL transcript and the
     English translation side by side. Never stores raw audio.';

-- ---------------------------------------------------------------------------
-- Indexes (read paths used by the admin dashboard and translation retry)
-- ---------------------------------------------------------------------------
create index if not exists idx_sessions_camp_created
    on public.feedback_sessions (camp_id, created_at desc);
create index if not exists idx_sessions_status
    on public.feedback_sessions (status);
create index if not exists idx_sessions_patient_code
    on public.feedback_sessions (patient_code);
create index if not exists idx_answers_session
    on public.feedback_answers (session_id);
create index if not exists idx_answers_rating
    on public.feedback_answers (rating) where rating is not null;
create index if not exists idx_answers_translation_retry
    on public.feedback_answers (id)
    where translation_status in ('pending', 'failed');

-- ---------------------------------------------------------------------------
-- Sequence resynchronisation.
-- After importing explicit SQLite IDs the identity sequences must be moved
-- past max(id), otherwise new inserts would collide with imported rows.
-- Call this once after every data import (the migration script does it too).
-- ---------------------------------------------------------------------------
create or replace function public.resync_identity_sequences()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
    execute format(
        'select setval(pg_get_serial_sequence(%L, %L),
                       greatest(coalesce(max(id), 0) + 1, 1), false)
         from %I.%I',
        'public.feedback_sessions', 'id', 'public', 'feedback_sessions');
    execute format(
        'select setval(pg_get_serial_sequence(%L, %L),
                       greatest(coalesce(max(id), 0) + 1, 1), false)
         from %I.%I',
        'public.feedback_answers', 'id', 'public', 'feedback_answers');
end;
$$;

grant execute on function public.resync_identity_sequences() to authenticated;
